import Foundation
import GRDB

/// Wishlist Service — CRUD for wishlist items that feed into procurement.
///
/// Wishlist items can be manually added or auto-generated by forecasting.
/// Items flow through: pending → approved → sent_to_procurement (or dismissed).
///
/// All queries run against the local SQLite database via GRDB.
/// Tables that may not yet exist are handled gracefully.
public final class WishlistService: Sendable {
    private let db: AppDatabase
    private let auth: AuthService

    public init(db: AppDatabase, auth: AuthService) {
        self.db = db
        self.auth = auth
    }

    // =========================================================================
    // MARK: - Error Types
    // =========================================================================

    public enum WishlistError: LocalizedError, Sendable, Equatable {
        case itemNotFound(Int64)
        case invalidStatus(String)
        case alreadyProcessed(Int64, String)
        case dismissReasonRequired
        case insufficientPermissions(required: String)
        case restrictedToAssignedTruckUser(locationId: Int64)
        case partNotFound(Int64)

        public var errorDescription: String? {
            switch self {
            case .itemNotFound(let id): "Wishlist item #\(id) not found"
            case .invalidStatus(let msg): msg
            case .alreadyProcessed(let id, let status):
                "Wishlist item #\(id) is already \(status)"
            case .dismissReasonRequired:
                "A dismiss reason is required"
            case .insufficientPermissions(let required):
                "You don't have permission to perform this action (required: \(required))"
            case .restrictedToAssignedTruckUser(let locationId):
                "Only the assigned truck user can route a physical audit for truck #\(locationId)"
            case .partNotFound(let id):
                "Part #\(id) not found"
            }
        }
    }

    // =========================================================================
    // MARK: - Result Types
    // =========================================================================

    /// Counts per status for smart-card display.
    public struct StatusCounts: Sendable {
        public let pending: Int
        public let approved: Int
        public let dismissed: Int
        public let sentToProcurement: Int
        public let total: Int

        public init(pending: Int = 0, approved: Int = 0, dismissed: Int = 0, sentToProcurement: Int = 0) {
            self.pending = pending
            self.approved = approved
            self.dismissed = dismissed
            self.sentToProcurement = sentToProcurement
            self.total = pending + approved + dismissed + sentToProcurement
        }
    }

    /// Result from evaluating one part/location against MIN stock routing rules.
    public struct BelowMinimumRoutingResult: Sendable {
        public let partId: Int64
        public let partName: String
        public let locationType: String
        public let locationId: Int64
        public let currentStock: Int
        public let minStock: Int
        public let targetStock: Int
        public let certaintyScore: Double
        public let action: String
        public let quantity: Int
        public let movementId: Int64?
        public let wishlistItem: WishlistItem?
        public let auditSessionId: Int64?
        public let reusedExistingAction: Bool

        public init(
            partId: Int64,
            partName: String,
            locationType: String,
            locationId: Int64,
            currentStock: Int,
            minStock: Int,
            targetStock: Int,
            certaintyScore: Double,
            action: String,
            quantity: Int,
            movementId: Int64? = nil,
            wishlistItem: WishlistItem? = nil,
            auditSessionId: Int64? = nil,
            reusedExistingAction: Bool = false
        ) {
            self.partId = partId
            self.partName = partName
            self.locationType = locationType
            self.locationId = locationId
            self.currentStock = currentStock
            self.minStock = minStock
            self.targetStock = targetStock
            self.certaintyScore = certaintyScore
            self.action = action
            self.quantity = quantity
            self.movementId = movementId
            self.wishlistItem = wishlistItem
            self.auditSessionId = auditSessionId
            self.reusedExistingAction = reusedExistingAction
        }
    }

    // =========================================================================
    // MARK: - List / Query
    // =========================================================================

    /// List wishlist items, optionally filtered by status.
    public func listItems(status: String? = nil) throws -> [WishlistItem] {
        do {
            return try db.writer.read { dbConn in
                var request = WishlistItem
                    .order(Column("created_at").desc)

                if let status = status {
                    request = request.filter(Column("status") == status)
                }

                return try request.fetchAll(dbConn)
            }
        } catch {
            if isTableNotFoundError(error) { return [] }
            throw error
        }
    }

    /// Get a single wishlist item by ID.
    public func getItem(id: Int64) throws -> WishlistItem? {
        do {
            return try db.writer.read { dbConn in
                try WishlistItem.fetchOne(dbConn, key: id)
            }
        } catch {
            if isTableNotFoundError(error) { return nil }
            throw error
        }
    }

    /// Get counts per status for smart-card filters.
    public func getStatusCounts() throws -> StatusCounts {
        do {
            return try db.writer.read { dbConn in
                let rows = try Row.fetchAll(dbConn, sql: """
                    SELECT status, COUNT(*) as cnt
                    FROM wishlist_items
                    GROUP BY status
                """)

                var pending = 0, approved = 0, dismissed = 0, sent = 0
                for row in rows {
                    let status: String = row["status"]
                    let count: Int = row["cnt"]
                    switch status {
                    case "pending": pending = count
                    case "approved": approved = count
                    case "dismissed": dismissed = count
                    case "sent_to_procurement": sent = count
                    default: break
                    }
                }
                return StatusCounts(pending: pending, approved: approved, dismissed: dismissed, sentToProcurement: sent)
            }
        } catch {
            if isTableNotFoundError(error) { return StatusCounts() }
            throw error
        }
    }

    // =========================================================================
    // MARK: - Create
    // =========================================================================

    /// Add a new wishlist item.
    @discardableResult
    public func addItem(
        partId: Int64? = nil,
        partName: String,
        qtySuggested: Int = 1,
        reason: String? = nil,
        priority: String = "normal",
        sourceType: String = "manual",
        requestedBy: String? = nil,
        notes: String? = nil,
        certaintyScore: Double? = nil
    ) throws -> WishlistItem {
        try db.writer.write { dbConn in
            let now = Date()
            let nowString = CoreFormatters.iso8601.string(from: now)
            // Manual items auto-approve after 14 days if no action taken
            let autoApprove: String? = sourceType == "manual"
                ? CoreFormatters.iso8601.string(from: now.addingTimeInterval(14 * 24 * 3600))
                : nil
            var item = WishlistItem(
                id: nil,
                partId: partId,
                partName: partName,
                qtySuggested: qtySuggested,
                reason: reason,
                priority: priority,
                sourceType: sourceType,
                status: "pending",
                requestedBy: requestedBy,
                approvedBy: nil,
                approvedAt: nil,
                dismissedBy: nil,
                dismissedAt: nil,
                dismissReason: nil,
                notes: notes,
                createdAt: nowString,
                updatedAt: nowString,
                autoApproveAt: autoApprove,
                certaintyScore: certaintyScore
            )
            try item.insert(dbConn)
            return item
        }
    }

    // =========================================================================
    // MARK: - Below-MIN Routing
    // =========================================================================

    /// Evaluate a part/location against MIN stock and route the operational action.
    ///
    /// Routing order:
    /// 1. If the target location is not below MIN, no action.
    /// 2. For truck/trailer shortages, pull available shop stock before procurement.
    /// 3. If shop cannot cover the field shortage and confidence is at least 80%,
    ///    create/approve one deduped system wishlist item.
    /// 4. If confidence is below 80%, route one deduped physical-count audit.
    @discardableResult
    public func routeBelowMinimumStock(
        partId: Int64,
        locationType rawLocationType: String,
        locationId: Int64,
        actorUserId: Int64,
        certaintyOverride: Double? = nil
    ) throws -> BelowMinimumRoutingResult {
        let locationType = normalizeLocationType(rawLocationType)

        return try db.writer.write { dbConn in
            let partName = try fetchPartName(dbConn, partId: partId)
            let target = try fetchLocationTarget(dbConn, partId: partId, locationType: locationType, locationId: locationId)
            let currentStock = try currentStock(dbConn, partId: partId, locationType: locationType, locationId: locationId)
            let certainty = certaintyOverride ?? target.certainty
            let qtyNeeded = max(0, max(target.targetStock, target.minStock) - currentStock)

            guard target.minStock > 0, currentStock < target.minStock else {
                return BelowMinimumRoutingResult(
                    partId: partId,
                    partName: partName,
                    locationType: locationType,
                    locationId: locationId,
                    currentStock: currentStock,
                    minStock: target.minStock,
                    targetStock: target.targetStock,
                    certaintyScore: certainty,
                    action: "none",
                    quantity: 0
                )
            }

            let marker = Self.belowMinimumMarker(partId: partId, locationType: locationType, locationId: locationId)

            if locationType == "truck" || locationType == "trailer" {
                let shopStock = try currentShopStock(dbConn, partId: partId)
                if shopStock > 0 {
                    if let existingMovementId = try existingShopTransferId(dbConn, marker: marker) {
                        return BelowMinimumRoutingResult(
                            partId: partId,
                            partName: partName,
                            locationType: locationType,
                            locationId: locationId,
                            currentStock: currentStock,
                            minStock: target.minStock,
                            targetStock: target.targetStock,
                            certaintyScore: certainty,
                            action: "shop_transfer",
                            quantity: min(qtyNeeded, shopStock),
                            movementId: existingMovementId,
                            reusedExistingAction: true
                        )
                    }

                    let movementQty = min(qtyNeeded, shopStock)
                    let movementId = try createShopTransfer(
                        dbConn,
                        partId: partId,
                        quantity: movementQty,
                        toLocationType: locationType,
                        toLocationId: locationId,
                        performedBy: actorUserId,
                        marker: marker
                    )
                    return BelowMinimumRoutingResult(
                        partId: partId,
                        partName: partName,
                        locationType: locationType,
                        locationId: locationId,
                        currentStock: currentStock,
                        minStock: target.minStock,
                        targetStock: target.targetStock,
                        certaintyScore: certainty,
                        action: "shop_transfer",
                        quantity: movementQty,
                        movementId: movementId
                    )
                }
            }

            guard certainty >= 0.8 else {
                try assertCanRoutePhysicalAudit(dbConn, actorUserId: actorUserId, locationType: locationType, locationId: locationId)
                if let existingAuditId = try existingAuditSessionId(dbConn, marker: marker) {
                    return BelowMinimumRoutingResult(
                        partId: partId,
                        partName: partName,
                        locationType: locationType,
                        locationId: locationId,
                        currentStock: currentStock,
                        minStock: target.minStock,
                        targetStock: target.targetStock,
                        certaintyScore: certainty,
                        action: "physical_audit",
                        quantity: qtyNeeded,
                        auditSessionId: existingAuditId,
                        reusedExistingAction: true
                    )
                }

                let auditId = try createPhysicalAuditSession(
                    dbConn,
                    partId: partId,
                    partName: partName,
                    locationType: locationType,
                    locationId: locationId,
                    startedBy: actorUserId,
                    marker: marker
                )
                return BelowMinimumRoutingResult(
                    partId: partId,
                    partName: partName,
                    locationType: locationType,
                    locationId: locationId,
                    currentStock: currentStock,
                    minStock: target.minStock,
                    targetStock: target.targetStock,
                    certaintyScore: certainty,
                    action: "physical_audit",
                    quantity: qtyNeeded,
                    auditSessionId: auditId
                )
            }

            if let existing = try existingWishlistItem(dbConn, marker: marker) {
                return BelowMinimumRoutingResult(
                    partId: partId,
                    partName: partName,
                    locationType: locationType,
                    locationId: locationId,
                    currentStock: currentStock,
                    minStock: target.minStock,
                    targetStock: target.targetStock,
                    certaintyScore: certainty,
                    action: "wishlist",
                    quantity: qtyNeeded,
                    wishlistItem: existing,
                    reusedExistingAction: true
                )
            }

            let item = try createApprovedBelowMinimumWishlist(
                dbConn,
                partId: partId,
                partName: partName,
                quantity: qtyNeeded,
                certaintyScore: certainty,
                locationType: locationType,
                locationId: locationId,
                marker: marker
            )
            return BelowMinimumRoutingResult(
                partId: partId,
                partName: partName,
                locationType: locationType,
                locationId: locationId,
                currentStock: currentStock,
                minStock: target.minStock,
                targetStock: target.targetStock,
                certaintyScore: certainty,
                action: "wishlist",
                quantity: qtyNeeded,
                wishlistItem: item
            )
        }
    }

    // =========================================================================
    // MARK: - Update
    // =========================================================================

    /// Update an existing wishlist item's editable fields.
    @discardableResult
    public func updateItem(
        id: Int64,
        partName: String? = nil,
        qtySuggested: Int? = nil,
        reason: String? = nil,
        priority: String? = nil,
        notes: String? = nil
    ) throws -> WishlistItem {
        try db.writer.write { dbConn in
            guard var item = try WishlistItem.fetchOne(dbConn, key: id) else {
                throw WishlistError.itemNotFound(id)
            }
            if let partName = partName { item.partName = partName }
            if let qtySuggested = qtySuggested { item.qtySuggested = qtySuggested }
            if let reason = reason { item.reason = reason }
            if let priority = priority { item.priority = priority }
            if let notes = notes { item.notes = notes }
            try item.update(dbConn)
            return item
        }
    }

    // =========================================================================
    // MARK: - Status Transitions
    // =========================================================================

    /// Approve a pending wishlist item.
    /// Requires the caller to hold the `wishlist.approve` permission.
    @discardableResult
    public func approveItem(id: Int64, byUserId: Int64) throws -> WishlistItem {
        guard try auth.hasPermission(byUserId, permissionKey: "wishlist.approve") else {
            throw WishlistError.insufficientPermissions(required: "wishlist.approve")
        }
        guard let userRecord = try auth.getUser(byUserId) else {
            throw WishlistError.insufficientPermissions(required: "wishlist.approve")
        }
        return try _performApprove(id: id, approvedByName: userRecord.displayName)
    }

    /// Dismiss a pending wishlist item. A reason is required.
    /// Requires the caller to hold the `wishlist.dismiss` permission.
    @discardableResult
    public func dismissItem(id: Int64, byUserId: Int64, reason: String) throws -> WishlistItem {
        guard try auth.hasPermission(byUserId, permissionKey: "wishlist.dismiss") else {
            throw WishlistError.insufficientPermissions(required: "wishlist.dismiss")
        }
        guard let userRecord = try auth.getUser(byUserId) else {
            throw WishlistError.insufficientPermissions(required: "wishlist.dismiss")
        }
        return try _performDismiss(id: id, dismissedByName: userRecord.displayName, reason: reason)
    }

    /// Mark an approved item as sent to procurement.
    /// Requires the caller to hold the `wishlist.send_to_procurement` permission.
    @discardableResult
    public func sendToProcurement(id: Int64, byUserId: Int64) throws -> WishlistItem {
        guard try auth.hasPermission(byUserId, permissionKey: "wishlist.send_to_procurement") else {
            throw WishlistError.insufficientPermissions(required: "wishlist.send_to_procurement")
        }
        return try db.writer.write { dbConn in
            guard var item = try WishlistItem.fetchOne(dbConn, key: id) else {
                throw WishlistError.itemNotFound(id)
            }
            guard item.status == "approved" else {
                throw WishlistError.invalidStatus(
                    "Only approved items can be sent to procurement (current: \(item.status))"
                )
            }
            item.status = "sent_to_procurement"
            try item.update(dbConn)
            return item
        }
    }

    /// Reopen a dismissed item back to pending.
    /// Requires the caller to hold the `wishlist.reopen` permission.
    @discardableResult
    public func reopenItem(id: Int64, byUserId: Int64) throws -> WishlistItem {
        guard try auth.hasPermission(byUserId, permissionKey: "wishlist.reopen") else {
            throw WishlistError.insufficientPermissions(required: "wishlist.reopen")
        }
        return try db.writer.write { dbConn in
            guard var item = try WishlistItem.fetchOne(dbConn, key: id) else {
                throw WishlistError.itemNotFound(id)
            }
            guard item.status == "dismissed" else {
                throw WishlistError.invalidStatus(
                    "Only dismissed items can be reopened (current: \(item.status))"
                )
            }
            item.status = "pending"
            item.dismissedBy = nil
            item.dismissedAt = nil
            try item.update(dbConn)
            return item
        }
    }

    // =========================================================================
    // MARK: - Internal State-Mutation Helpers (no permission check)
    // =========================================================================

    /// Internal approve — called by `processAutoApprovals` (system or permissioned path).
    @discardableResult
    private func _performApprove(id: Int64, approvedByName: String) throws -> WishlistItem {
        try db.writer.write { dbConn in
            guard var item = try WishlistItem.fetchOne(dbConn, key: id) else {
                throw WishlistError.itemNotFound(id)
            }
            guard item.status == "pending" else {
                throw WishlistError.alreadyProcessed(id, item.status)
            }
            item.status = "approved"
            item.approvedBy = approvedByName
            item.approvedAt = Self.nowString()
            try item.update(dbConn)
            return item
        }
    }

    /// Internal dismiss — called by system paths that bypass the permission gate.
    @discardableResult
    private func _performDismiss(id: Int64, dismissedByName: String, reason: String) throws -> WishlistItem {
        guard !reason.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            throw WishlistError.dismissReasonRequired
        }
        return try db.writer.write { dbConn in
            guard var item = try WishlistItem.fetchOne(dbConn, key: id) else {
                throw WishlistError.itemNotFound(id)
            }
            guard item.status == "pending" || item.status == "approved" else {
                throw WishlistError.alreadyProcessed(id, item.status)
            }
            item.status = "dismissed"
            item.dismissedBy = dismissedByName
            item.dismissedAt = Self.nowString()
            item.dismissReason = reason.trimmingCharacters(in: .whitespacesAndNewlines)
            try item.update(dbConn)
            return item
        }
    }

    // =========================================================================
    // MARK: - Delete
    // =========================================================================

    /// Permanently delete a wishlist item.
    public func deleteItem(id: Int64) throws {
        try db.writer.write { dbConn in
            guard let item = try WishlistItem.fetchOne(dbConn, key: id) else {
                throw WishlistError.itemNotFound(id)
            }
            try item.delete(dbConn)
        }
    }

    // =========================================================================
    // MARK: - Sectioned Items & Auto-Approvals
    // =========================================================================

    /// Items grouped by source type for the 3-section UI layout.
    public struct WishlistSections: Sendable {
        public let userAdded: [WishlistItem]       // source_type = "manual"
        public let forecastDemand: [WishlistItem]  // source_type = "forecast"
        public let autoAdded: [WishlistItem]       // source_type = "system"

        public init(userAdded: [WishlistItem] = [], forecastDemand: [WishlistItem] = [], autoAdded: [WishlistItem] = []) {
            self.userAdded = userAdded
            self.forecastDemand = forecastDemand
            self.autoAdded = autoAdded
        }
    }

    /// Returns wishlist items split into 3 sections by source_type.
    /// Fetches wishlist items grouped into three sections: User Added, Forecast Demand, System Auto-Added.
    /// Call `processAutoApprovals(byUserId:)` before this method (in a background task) to keep auto-approval state current.
    public func getSectionedItems(statusFilter: String? = nil) throws -> WishlistSections {
        return try db.writer.read { dbConn in
            var base = WishlistItem
                .order(Column("created_at").desc)

            if let statusFilter = statusFilter {
                base = base.filter(Column("status") == statusFilter)
            }

            let all = try base.fetchAll(dbConn)

            let userAdded = all.filter { $0.sourceType == "manual" }
            let forecastDemand = all.filter { $0.sourceType == "forecast" }
            let autoAdded = all.filter { $0.sourceType != "manual" && $0.sourceType != "forecast" }

            return WishlistSections(userAdded: userAdded, forecastDemand: forecastDemand, autoAdded: autoAdded)
        }
    }

    /// Auto-approve any pending items whose auto_approve_at has passed.
    ///
    /// - Parameter byUserId: The ID of the user triggering auto-approval. When non-nil, the caller
    ///   must hold the `wishlist.auto_approve` permission; otherwise
    ///   `WishlistError.insufficientPermissions` is thrown. When nil (background/system path)
    ///   the approval is attributed to `"System (Auto)"` with no permission check.
    ///
    /// - Returns: The count of items that were auto-approved.
    @discardableResult
    public func processAutoApprovals(byUserId: Int64?) throws -> Int {
        let approverName: String
        if let userId = byUserId {
            guard try auth.hasPermission(userId, permissionKey: "wishlist.auto_approve") else {
                throw WishlistError.insufficientPermissions(required: "wishlist.auto_approve")
            }
            guard let userRecord = try auth.getUser(userId) else {
                throw WishlistError.insufficientPermissions(required: "wishlist.auto_approve")
            }
            approverName = userRecord.displayName
        } else {
            approverName = "System (Auto)"
        }

        do {
            let now = Self.nowString()
            let expiredItems = try db.writer.read { dbConn in
                try WishlistItem
                    .filter(Column("status") == "pending")
                    .filter(Column("auto_approve_at") != nil)
                    .filter(Column("auto_approve_at") <= now)
                    .fetchAll(dbConn)
            }

            var count = 0
            for item in expiredItems {
                guard let id = item.id else { continue }
                _ = try _performApprove(id: id, approvedByName: approverName)
                count += 1
            }
            return count
        } catch {
            if isTableNotFoundError(error) { return 0 }
            throw error
        }
    }

    private struct BelowMinimumTarget {
        let minStock: Int
        let targetStock: Int
        let certainty: Double
    }

    private static func belowMinimumMarker(partId: Int64, locationType: String, locationId: Int64) -> String {
        "[below-min part:\(partId) location:\(locationType):\(locationId)]"
    }

    private func normalizeLocationType(_ locationType: String) -> String {
        let trimmed = locationType.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return trimmed == "vehicle" ? "truck" : trimmed
    }

    private func fetchPartName(_ dbConn: Database, partId: Int64) throws -> String {
        guard let name = try String.fetchOne(
            dbConn,
            sql: "SELECT name FROM parts WHERE id = ? AND deleted_at IS NULL",
            arguments: [partId]
        ) else {
            throw WishlistError.partNotFound(partId)
        }
        return name
    }

    private func fetchLocationTarget(
        _ dbConn: Database,
        partId: Int64,
        locationType: String,
        locationId: Int64
    ) throws -> BelowMinimumTarget {
        if let row = try Row.fetchOne(dbConn, sql: """
            SELECT min_stock, target_stock, certainty_rating
            FROM location_stock_targets
            WHERE part_id = ? AND location_type = ? AND location_id = ? AND deleted_at IS NULL
            """, arguments: [partId, locationType, locationId]) {
            return BelowMinimumTarget(
                minStock: row["min_stock"] ?? 0,
                targetStock: row["target_stock"] ?? 0,
                certainty: row["certainty_rating"] ?? 0.0
            )
        }

        if let row = try Row.fetchOne(dbConn, sql: """
            SELECT min_stock_level, target_stock_level
            FROM parts
            WHERE id = ? AND deleted_at IS NULL
            """, arguments: [partId]) {
            return BelowMinimumTarget(
                minStock: row["min_stock_level"] ?? 0,
                targetStock: row["target_stock_level"] ?? 0,
                certainty: 0.0
            )
        }

        throw WishlistError.partNotFound(partId)
    }

    private func currentStock(
        _ dbConn: Database,
        partId: Int64,
        locationType: String,
        locationId: Int64
    ) throws -> Int {
        switch locationType {
        case "truck":
            return try Int.fetchOne(dbConn, sql: """
                SELECT COALESCE(SUM(quantity), 0)
                FROM vehicle_stock
                WHERE part_id = ? AND vehicle_id = ? AND stock_type = 'truck_stock' AND deleted_at IS NULL
                """, arguments: [partId, locationId]) ?? 0
        case "trailer":
            return try Int.fetchOne(dbConn, sql: """
                SELECT COALESCE(SUM(quantity), 0)
                FROM trailer_stock
                WHERE part_id = ? AND trailer_id = ? AND deleted_at IS NULL
                """, arguments: [partId, locationId]) ?? 0
        default:
            return try Int.fetchOne(dbConn, sql: """
                SELECT COALESCE(SUM(qty), 0)
                FROM stock
                WHERE part_id = ? AND location_type = ? AND location_id = ? AND deleted_at IS NULL
                """, arguments: [partId, locationType, locationId]) ?? 0
        }
    }

    private func currentShopStock(_ dbConn: Database, partId: Int64) throws -> Int {
        try Int.fetchOne(dbConn, sql: """
            SELECT COALESCE(MAX(qty), 0)
            FROM stock
            WHERE part_id = ?
              AND location_type IN ('shop', 'warehouse')
              AND deleted_at IS NULL
            """, arguments: [partId]) ?? 0
    }

    private func existingShopTransferId(_ dbConn: Database, marker: String) throws -> Int64? {
        try Int64.fetchOne(dbConn, sql: """
            SELECT id
            FROM stock_movements
            WHERE movement_type = 'restock_from_shop'
              AND notes LIKE ?
              AND deleted_at IS NULL
            ORDER BY id DESC
            LIMIT 1
            """, arguments: ["%\(marker)%"])
    }

    private func createShopTransfer(
        _ dbConn: Database,
        partId: Int64,
        quantity: Int,
        toLocationType: String,
        toLocationId: Int64,
        performedBy: Int64,
        marker: String
    ) throws -> Int64 {
        let source = try shopSourceLocation(dbConn, partId: partId, quantity: quantity)
        try dbConn.execute(sql: """
            INSERT INTO stock_movements
            (part_id, qty, from_location_type, from_location_id, to_location_type, to_location_id,
             movement_type, reason, notes, performed_by, created_at)
            VALUES (?, ?, ?, ?, ?, ?, 'restock_from_shop', 'Below MIN restock from shop', ?, ?, datetime('now'))
            """, arguments: [
                partId, quantity, source.locationType, source.locationId,
                toLocationType, toLocationId, "\(marker) Generated below-MIN shop restock.", performedBy
            ])
        let movementId = dbConn.lastInsertedRowID

        try dbConn.execute(sql: """
            UPDATE stock SET qty = qty - ?, updated_at = datetime('now')
            WHERE part_id = ? AND location_type = ? AND location_id = ? AND deleted_at IS NULL
            """, arguments: [quantity, partId, source.locationType, source.locationId])

        try dbConn.execute(sql: """
            UPDATE stock SET qty = qty + ?, updated_at = datetime('now')
            WHERE part_id = ? AND location_type = ? AND location_id = ? AND deleted_at IS NULL
            """, arguments: [quantity, partId, toLocationType, toLocationId])
        if dbConn.changesCount == 0 {
            try dbConn.execute(sql: """
                INSERT INTO stock (part_id, location_type, location_id, qty, updated_at)
                VALUES (?, ?, ?, ?, datetime('now'))
                """, arguments: [partId, toLocationType, toLocationId, quantity])
        }

        if toLocationType == "truck" {
            try dbConn.execute(sql: """
                UPDATE vehicle_stock SET quantity = quantity + ?, updated_at = datetime('now')
                WHERE part_id = ? AND vehicle_id = ? AND stock_type = 'truck_stock' AND deleted_at IS NULL
                """, arguments: [quantity, partId, toLocationId])
            if dbConn.changesCount == 0 {
                let partName = try fetchPartName(dbConn, partId: partId)
                try dbConn.execute(sql: """
                    INSERT INTO vehicle_stock
                    (vehicle_id, part_id, part_name, quantity, stock_type, created_at, updated_at)
                    VALUES (?, ?, ?, ?, 'truck_stock', datetime('now'), datetime('now'))
                    """, arguments: [toLocationId, partId, partName, quantity])
            }
        } else if toLocationType == "trailer" {
            try dbConn.execute(sql: """
                UPDATE trailer_stock SET quantity = quantity + ?, updated_at = datetime('now')
                WHERE part_id = ? AND trailer_id = ? AND deleted_at IS NULL
                """, arguments: [quantity, partId, toLocationId])
            if dbConn.changesCount == 0 {
                let partName = try fetchPartName(dbConn, partId: partId)
                try dbConn.execute(sql: """
                    INSERT INTO trailer_stock
                    (trailer_id, part_id, part_name, quantity, created_at, updated_at)
                    VALUES (?, ?, ?, ?, datetime('now'), datetime('now'))
                    """, arguments: [toLocationId, partId, partName, quantity])
            }
        }

        return movementId
    }

    private func shopSourceLocation(_ dbConn: Database, partId: Int64, quantity: Int) throws -> (locationType: String, locationId: Int64) {
        if let row = try Row.fetchOne(dbConn, sql: """
            SELECT location_type, location_id
            FROM stock
            WHERE part_id = ?
              AND location_type IN ('shop', 'warehouse')
              AND qty >= ?
              AND deleted_at IS NULL
            ORDER BY CASE location_type WHEN 'shop' THEN 0 ELSE 1 END, location_id
            LIMIT 1
            """, arguments: [partId, quantity]) {
            return (row["location_type"] ?? "warehouse", row["location_id"] ?? 1)
        }

        let row = try Row.fetchOne(dbConn, sql: """
            SELECT location_type, location_id
            FROM stock
            WHERE part_id = ?
              AND location_type IN ('shop', 'warehouse')
              AND qty > 0
              AND deleted_at IS NULL
            ORDER BY qty DESC
            LIMIT 1
            """, arguments: [partId])
        guard let row else { return ("warehouse", 1) }
        return (row["location_type"] ?? "warehouse", row["location_id"] ?? 1)
    }

    private func existingWishlistItem(_ dbConn: Database, marker: String) throws -> WishlistItem? {
        try WishlistItem.fetchOne(dbConn, sql: """
            SELECT *
            FROM wishlist_items
            WHERE source_type = 'system'
              AND status IN ('pending', 'approved')
              AND notes LIKE ?
            ORDER BY id DESC
            LIMIT 1
            """, arguments: ["%\(marker)%"])
    }

    private func createApprovedBelowMinimumWishlist(
        _ dbConn: Database,
        partId: Int64,
        partName: String,
        quantity: Int,
        certaintyScore: Double,
        locationType: String,
        locationId: Int64,
        marker: String
    ) throws -> WishlistItem {
        let nowString = Self.nowString()
        var item = WishlistItem(
            id: nil,
            partId: partId,
            partName: partName,
            qtySuggested: quantity,
            reason: "Below MIN at \(locationType) #\(locationId)",
            priority: "high",
            sourceType: "system",
            status: "approved",
            requestedBy: "System (Below MIN)",
            approvedBy: "System (Below MIN)",
            approvedAt: nowString,
            dismissedBy: nil,
            dismissedAt: nil,
            dismissReason: nil,
            notes: "\(marker) Shop stock unavailable; confidence \(Int(certaintyScore * 100))%.",
            createdAt: nowString,
            updatedAt: nowString,
            autoApproveAt: nil,
            certaintyScore: certaintyScore
        )
        try item.insert(dbConn)
        return item
    }

    private func assertCanRoutePhysicalAudit(
        _ dbConn: Database,
        actorUserId: Int64,
        locationType: String,
        locationId: Int64
    ) throws {
        guard try userHasPermission(dbConn, userId: actorUserId, permissionKey: "perform_audit") else {
            throw WishlistError.insufficientPermissions(required: "perform_audit")
        }

        guard locationType == "truck" else { return }
        if try userHasPermission(dbConn, userId: actorUserId, permissionKey: "manage_trucks") { return }

        let isAssigned = try Int.fetchOne(dbConn, sql: """
            SELECT COUNT(*)
            FROM vehicle_assignments
            WHERE vehicle_id = ? AND user_id = ? AND is_active = 1 AND deleted_at IS NULL
            """, arguments: [locationId, actorUserId]) ?? 0
        guard isAssigned > 0 else {
            throw WishlistError.restrictedToAssignedTruckUser(locationId: locationId)
        }
    }

    private func userHasPermission(_ dbConn: Database, userId: Int64, permissionKey: String) throws -> Bool {
        let count = try Int.fetchOne(dbConn, sql: """
            SELECT COUNT(*)
            FROM user_hats uh
            JOIN users u ON u.id = uh.user_id
            JOIN hat_permissions hp ON hp.hat_id = uh.hat_id
            WHERE uh.user_id = ?
              AND uh.is_active = 1 AND uh.deleted_at IS NULL
              AND u.deleted_at IS NULL AND u.is_active = 1
              AND hp.permission_key = ?
            LIMIT 1
            """, arguments: [userId, permissionKey]) ?? 0
        return count > 0
    }

    private func existingAuditSessionId(_ dbConn: Database, marker: String) throws -> Int64? {
        try Int64.fetchOne(dbConn, sql: """
            SELECT id
            FROM audit_sessions_v2
            WHERE session_type = 'physical_count'
              AND status = 'active'
              AND notes LIKE ?
              AND deleted_at IS NULL
            ORDER BY id DESC
            LIMIT 1
            """, arguments: ["%\(marker)%"])
    }

    private func createPhysicalAuditSession(
        _ dbConn: Database,
        partId: Int64,
        partName: String,
        locationType: String,
        locationId: Int64,
        startedBy: Int64,
        marker: String
    ) throws -> Int64 {
        try dbConn.execute(sql: """
            INSERT INTO audit_sessions_v2
            (session_type, started_by, status, notes, started_at)
            VALUES ('physical_count', ?, 'active', ?, datetime('now'))
            """, arguments: [
                startedBy,
                "\(marker) Count \(partName) (part #\(partId)) at \(locationType) #\(locationId) before wishlist generation."
            ])
        return dbConn.lastInsertedRowID
    }

    // =========================================================================
    // MARK: - Helpers
    // =========================================================================

    private static func nowString() -> String { CoreFormatters.nowISO() }

    private func isTableNotFoundError(_ error: Error) -> Bool {
        let message = String(describing: error)
        return message.contains("no such table") || message.contains("no such column")
    }
}
